package com.thang.user.service.user;
import com.nihongo.security.SecurityKeyFiles;import org.springframework.stereotype.Component;import org.springframework.core.env.Environment;import javax.crypto.*;import javax.crypto.spec.*;import java.security.SecureRandom;import java.nio.charset.StandardCharsets;import java.util.*;
@Component public class SessionTokenCipher {
 private final SecretKeySpec key;private final SecureRandom random=new SecureRandom();
 public SessionTokenCipher(Environment env){byte[] bytes=SecurityKeyFiles.secret(env.getProperty("security.session.encryption-key",""),env.getProperty("security.session.encryption-key-path",".local/security/session-encryption.key"));if(bytes.length!=32)throw new IllegalStateException("Session encryption needs a 32-byte key");key=new SecretKeySpec(bytes,"AES");}
 public String encrypt(String userId,String token){try{byte[] iv=new byte[12];random.nextBytes(iv);Cipher c=Cipher.getInstance("AES/GCM/NoPadding");c.init(Cipher.ENCRYPT_MODE,key,new GCMParameterSpec(128,iv));c.updateAAD(userId.getBytes(StandardCharsets.UTF_8));byte[] body=c.doFinal(token.getBytes(StandardCharsets.UTF_8));byte[] result=new byte[iv.length+body.length];System.arraycopy(iv,0,result,0,iv.length);System.arraycopy(body,0,result,iv.length,body.length);return Base64.getEncoder().encodeToString(result);}catch(Exception e){throw new IllegalStateException("Session encryption failed",e);}}
 public String decrypt(String userId,String encrypted){try{byte[] bytes=Base64.getDecoder().decode(encrypted);if(bytes.length<28)throw new IllegalArgumentException();Cipher c=Cipher.getInstance("AES/GCM/NoPadding");c.init(Cipher.DECRYPT_MODE,key,new GCMParameterSpec(128,Arrays.copyOfRange(bytes,0,12)));c.updateAAD(userId.getBytes(StandardCharsets.UTF_8));return new String(c.doFinal(Arrays.copyOfRange(bytes,12,bytes.length)),StandardCharsets.UTF_8);}catch(Exception e){throw new IllegalStateException("Session decryption failed",e);}}
}
